import math

state = 'pull_forward'
start_prog = None

def control(obs):
    global state, start_prog
    look_deg = -23.0  # keep camera screen in sight
    prog = obs['progress']['covered']
    hitch = obs['hitch_deg']
    hold = obs['motion']['hold_s']

    if hold > 0.05:
        return 0.0, 0.0, look_deg

    # Note from briefing: "When pulling forward to unstick, pull ahead straight or slightly right by at least two metres, because pulling forward while steering left swings the car front into the outer barrier."
    # So pull forward straight or steer slightly right!
    if state == 'pull_forward':
        if start_prog is None:
            start_prog = prog
        if prog > max(0.0, start_prog - 4.5):
            return -2.0, 1.2, look_deg
        else:
            state = 'reverse_corridor'

    # Reverse phase:
    views = obs.get('views', {})
    cam = views.get('camera')

    # Calculate nearest barrier distance on the left side
    min_left_cam = 999.0
    if cam and 'walls' in cam:
        for b_deg, d in cam['walls']:
            rad = math.radians(b_deg)
            y = d * math.sin(rad)
            x = d * math.cos(rad)
            if x < 0 and y > 0.1:
                if d < min_left_cam:
                    min_left_cam = d

    target_speed = -0.7

    # Before turning (up to ~14m), stay away from left rail
    if prog < 14.0:
        if min_left_cam < 1.2:
            target_hitch = -6.0
        elif min_left_cam < 1.6:
            target_hitch = -3.5
        else:
            target_hitch = -1.5
    elif prog < 19.5:
        if min_left_cam < 1.1:
            target_hitch = 6.0
        elif min_left_cam < 1.4:
            target_hitch = 12.0
        else:
            target_hitch = 18.0
    else:
        target_hitch = 0.0

    k_p = 2.4
    steer = k_p * (hitch - target_hitch)
    steer = max(-34.0, min(34.0, steer))

    return steer, target_speed, look_deg

