            rad = math.radians(b_deg)
            y = d * math.sin(rad)
            if y > 0 and d < min_dist_left:
                min_dist_left = d

    if prog < 18.0:
        if min_dist_left < 1.0:
            target_hitch = 8.0
        elif min_dist_left < 1.4:
            target_hitch = 14.0
        else:
            target_hitch = 20.0
    else:
        target_hitch = 0.0

    target_speed = -0.65
    k_p = 2.4
    steer = k_p * (hitch - target_hitch)
    steer = max(-34.0, min(34.0, steer))

    return steer, target_speed, look_deg

